	if (!d || !format)
		return;

	char chatbuf[CHAT_MAX_LEN + 1];
	va_list args;

	// MT2009_PLUS_LANGUAGE_V1 (chat): a line in the reader's language - the Polish format's translation (the same conversions), else
	// the whole line looked up (a notice, a quest's syschat); never the client's commands, never players' chat.
	const char* langFormat = Mt2009LanguageChatFormat(this, type, format);
	va_start(args, format);
	int len = vsnprintf(chatbuf, sizeof(chatbuf), langFormat, args);
	va_end(args);
	len = Mt2009LanguageChatResult(this, type, langFormat != format, chatbuf, sizeof(chatbuf), len);

